CREATE TABLE households(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner text UNIQUE NOT NULL, name text NOT NULL, currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'), timezone text NOT NULL, starting_funds bigint NOT NULL DEFAULT 0, demo boolean NOT NULL DEFAULT false);
CREATE TABLE accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households, name text NOT NULL, type text NOT NULL CHECK(type IN ('checking','savings','cash','credit')), opening_date date NOT NULL, opening_balance bigint NOT NULL, archived boolean NOT NULL DEFAULT false, UNIQUE(household_id,id));
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households, name text NOT NULL, rollover boolean NOT NULL DEFAULT true, archived boolean NOT NULL DEFAULT false, UNIQUE(household_id,id));
CREATE TABLE targets(household_id uuid NOT NULL REFERENCES households, category_id uuid NOT NULL, year int NOT NULL CHECK(year BETWEEN 2000 AND 2200), amount bigint NOT NULL CHECK(amount>=0), PRIMARY KEY(household_id,category_id,year), FOREIGN KEY(household_id,category_id) REFERENCES categories(household_id,id));
CREATE TABLE allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households, category_id uuid NOT NULL, month date NOT NULL CHECK(extract(day from month)=1), amount bigint NOT NULL, FOREIGN KEY(household_id,category_id) REFERENCES categories(household_id,id));
CREATE TABLE transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households, kind text NOT NULL CHECK(kind IN ('income','expense','refund','transfer')), date date NOT NULL, payee text NOT NULL, memo text NOT NULL DEFAULT '', amount bigint NOT NULL CHECK(amount>0), source text NOT NULL DEFAULT 'manual', external_id text, source_account uuid NOT NULL, original_id uuid, voided boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(household_id,id), FOREIGN KEY(household_id,source_account) REFERENCES accounts(household_id,id), FOREIGN KEY(household_id,original_id) REFERENCES transactions(household_id,id));
CREATE UNIQUE INDEX source_identity ON transactions(source_account,source,external_id) WHERE external_id IS NOT NULL;
CREATE TABLE entries(household_id uuid NOT NULL, transaction_id uuid NOT NULL, account_id uuid NOT NULL, amount bigint NOT NULL CHECK(amount<>0), PRIMARY KEY(transaction_id,account_id), FOREIGN KEY(household_id,transaction_id) REFERENCES transactions(household_id,id), FOREIGN KEY(household_id,account_id) REFERENCES accounts(household_id,id));
CREATE TABLE splits(household_id uuid NOT NULL, transaction_id uuid NOT NULL, category_id uuid NOT NULL, amount bigint NOT NULL CHECK(amount>0), PRIMARY KEY(transaction_id,category_id), FOREIGN KEY(household_id,transaction_id) REFERENCES transactions(household_id,id), FOREIGN KEY(household_id,category_id) REFERENCES categories(household_id,id));
CREATE FUNCTION validate_ledger() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE t transactions; n int; total bigint; st bigint;
BEGIN
 SELECT * INTO t FROM transactions WHERE id=NEW.id;
 SELECT count(*),sum(amount) INTO n,total FROM entries WHERE transaction_id=t.id;
 SELECT COALESCE(sum(amount),0) INTO st FROM splits WHERE transaction_id=t.id;
 IF (t.kind='transfer' AND (n<>2 OR total<>0)) OR (t.kind<>'transfer' AND (n<>1 OR total<>CASE WHEN t.kind='expense' THEN -t.amount ELSE t.amount END)) OR (t.kind IN ('expense','refund') AND st<>t.amount) OR (t.kind IN ('income','transfer') AND st<>0) THEN RAISE EXCEPTION 'Ledger invariant violation' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER ledger_valid AFTER INSERT ON transactions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_ledger();
CREATE TABLE profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households, name text NOT NULL, config jsonb NOT NULL, version int NOT NULL DEFAULT 1, UNIQUE(household_id,id));
CREATE TABLE batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households, account_id uuid NOT NULL, profile_id uuid NOT NULL, settings jsonb NOT NULL, content_hash text NOT NULL, settings_hash text NOT NULL, filename text NOT NULL, status text NOT NULL DEFAULT 'review' CHECK(status IN ('review','complete')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(household_id,account_id,content_hash,settings_hash), UNIQUE(household_id,id), FOREIGN KEY(household_id,account_id) REFERENCES accounts(household_id,id), FOREIGN KEY(household_id,profile_id) REFERENCES profiles(household_id,id));
CREATE TABLE import_rows(household_id uuid NOT NULL, batch_id uuid NOT NULL, row_number int NOT NULL, fingerprint text NOT NULL, parsed jsonb NOT NULL, error text, duplicate text, decision text CHECK(decision IN ('accept','skip','not_duplicate')), transaction_id uuid REFERENCES transactions, PRIMARY KEY(batch_id,row_number), FOREIGN KEY(household_id,batch_id) REFERENCES batches(household_id,id));
CREATE TABLE idempotency(household_id uuid NOT NULL REFERENCES households, operation text NOT NULL, key text NOT NULL, hash text NOT NULL, response jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(household_id,operation,key));
CREATE TABLE audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, household_id uuid NOT NULL REFERENCES households, actor text NOT NULL, action text NOT NULL, entity text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reconciliations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households, account_id uuid NOT NULL, date date NOT NULL, statement bigint NOT NULL, calculated bigint NOT NULL, difference bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(household_id,account_id) REFERENCES accounts(household_id,id));
